import numpy as np

# dx/dt = -2x + 4t, x(0) = 1. Solution exacte : x(t) = 2t - 1 + 2*exp(-2t).
def champ(x, t):
    return -2 * x + 4 * t

def exact(t):
    return 2 * t - 1 + 2 * np.exp(-2 * t)

for n in (2, 10, 100):
    h = 1 / n
    x = 1.0
    for i in range(n):
        x = x + h * champ(x, i * h)
    print(f"{n:3d} pas : erreur finale = {abs(x - exact(1.0)):.4f}")
